from pyspark.sql import functions as F


def solve(attribution_events):
    first = F.col("position") == 1
    last = F.col("position") == F.col("touches_in_path")
    return attribution_events.groupBy("campaign_id").agg(
        F.sum(F.when(first, 1)).alias("first_touches"),
        F.sum(F.when(last, 1)).alias("last_touches"),
    )
